// ============================================================
// SMART FILTER + INTENT - THEXUONG TELEGRAM BOT
// ============================================================


// ============================================================
// 1. HELPER FUNCTIONS
// ============================================================

function sanitize(str) {
  return String(str ?? '')
    .replace(/[\r\n\t]/g, ' ')
    .replace(/[\x00-\x1F\x7F]/g, ' ')
    .trim();
}

function normalize(str) {
  return String(str ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // Bỏ dấu tiếng Việt
    .replace(/đ/g, 'd')
    .replace(/[^a-z0-9\s]/g, '')
    .trim();
}

function fuzzyMatch(keyword, message) {
  const rawKeyword = String(keyword ?? '').toLowerCase();
  const rawMessage = String(message ?? '').toLowerCase();

  // Exact match trước
  if (rawMessage.includes(rawKeyword)) {
    return true;
  }

  // Bỏ dấu rồi kiểm tra
  const normKw = normalize(rawKeyword);
  const normMsg = normalize(rawMessage);

  if (normMsg.includes(normKw)) {
    return true;
  }

  // Cho phép thiếu 1 ký tự để xử lý lỗi gõ đơn giản
  // Partial phải bắt đầu ở đầu từ (tránh "đơn hàng" match nhầm "còn hàng")
  if (normKw.length >= 4) {
    for (let i = 0; i < normKw.length; i++) {
      const partial =
        normKw.slice(0, i) +
        normKw.slice(i + 1);

      if (partial.length >= 3) {
        const idx = normMsg.indexOf(partial);

        if (idx !== -1) {
          const prevChar = normMsg[idx - 1];

          if (idx === 0 || prevChar === ' ') {
            return true;
          }
        }
      }
    }
  }

  return false;
}


// ============================================================
// 2. LẤY DỮ LIỆU TELEGRAM
// ============================================================

const telegramData =
  $('Kiểm Tra Loại Message').item.json ?? {};

const telegramMessage =
  telegramData.message ?? {};

const userMessage =
  String(telegramMessage.text ?? '').trim();

const chatId =
  telegramMessage.chat?.id;

const userName =
  telegramMessage.from?.first_name || 'Bạn';


// Không có chatId thì dừng để tránh lỗi phía sau
if (chatId === undefined || chatId === null) {
  throw new Error(
    'Smart Filter + Intent: Không tìm thấy message.chat.id từ node "Kiểm Tra Loại Message".'
  );
}


// ============================================================
// 3. RATE LIMIT
// 5 REQUEST / 10 GIÂY / CHAT
// ============================================================

const now = Date.now();

if (!globalThis.rateLimitMap) {
  globalThis.rateLimitMap = new Map();
}

const userRequests =
  globalThis.rateLimitMap.get(chatId) || [];

const recentRequests =
  userRequests.filter(timestamp => {
    return now - timestamp < 10000;
  });


// Nếu >= 5 request trong 10 giây
if (recentRequests.length >= 5) {
  return [
    {
      json: {
        chatId,
        userName: sanitize(userName),
        userMessage: sanitize(userMessage),

        intent: 'rate_limited',
        isPolicy: false,

        productContext:
          'Không tìm thấy sản phẩm phù hợp',

        faqContext:
          'Không có FAQ phù hợp',

        orderPhone: null,
        orderId: null,
        needOrderFetch: false,

        timestamp:
          new Date().toISOString(),

        isGreetingOnly: false,

        secondaryIntents: [],

        mentionedProductIds: [],

        _rateLimited: true
      }
    }
  ];
}


// Ghi nhận request hiện tại
recentRequests.push(now);

globalThis.rateLimitMap.set(
  chatId,
  recentRequests
);


// ============================================================
// 4. LẤY DATA PRODUCT + FAQ TỪ INPUT
// ============================================================

const allItems = $input.all();

const products = [];
const faqs = [];


for (const item of allItems) {
  const resp = item?.json ?? {};

  const dataArr =
    resp.data !== undefined
      ? resp.data
      : resp;

  const rows =
    Array.isArray(dataArr)
      ? dataArr
      : [dataArr];


  for (const row of rows) {

    // Tránh lỗi nếu API trả null
    if (!row || typeof row !== 'object') {
      continue;
    }


    // ========================================================
    // PRODUCT
    // ========================================================

    if (
      row.id !== undefined &&
      row.id !== null &&
      row.name &&
      row.price !== undefined
    ) {

      const price = Number(row.price);

      products.push({
        id: String(row.id ?? ''),

        name:
          String(row.name ?? '')
            .toLowerCase(),

        name_orig:
          String(row.name ?? ''),

        brand:
          String(row.brand ?? '')
            .toLowerCase(),

        brand_orig:
          String(row.brand ?? ''),

        sport:
          String(row.sport ?? ''),

        category:
          String(row.category ?? ''),

        price:
          Number.isFinite(price)
            ? price
            : 0,

        description:
          String(row.description ?? ''),

        stock:
          String(
            row.stockStatus ??
            'Không rõ'
          )
      });
    }


    // ========================================================
    // FAQ
    // ========================================================

    if (row.topic && row.answer) {
      faqs.push({
        topic:
          String(row.topic ?? ''),

        keywords:
          String(
            row.questionKeywords ?? ''
          ).toLowerCase(),

        answer:
          String(row.answer ?? '')
      });
    }
  }
}


// ============================================================
// 5. INTENT DETECTION
// ============================================================

const msg =
  userMessage.toLowerCase();


const INTENT_MAP = [

  [
    'exchange',
    [
      'đổi hàng',
      'trả hàng',
      'hoàn tiền',
      'đổi size',
      'đổi trả',
      'đổi',
      'trả',
      'hoàn'
    ]
  ],

  [
    'shipping',
    [
      'phí ship',
      'giao hàng',
      'vận chuyển',
      'thời gian giao',
      'ship',
      'bao lâu'
    ]
  ],

  [
    'payment',
    [
      'thanh toán',
      'trả tiền',
      'cod',
      'chuyển khoản',
      'momo',
      'zalopay',
      'zalo',
      'thẻ'
    ]
  ],

  [
    'warranty',
    [
      'bảo hành',
      'hàng lỗi',
      'lỗi hàng',
      'bảo hành mấy tháng'
    ]
  ],

  [
    'stock',
    [
      'còn hàng',
      'còn không',
      'hết hàng',
      'có hàng',
      'tồn kho',
      'còn size',
      'hết size'
    ]
  ],

  [
    'compare',
    [
      'so sánh',
      'khác nhau',
      'tốt hơn',
      'nên chọn',
      'hay là'
    ]
  ],

  [
    'describe',
    [
      'mô tả',
      'giới thiệu',
      'thông tin',
      'chi tiết',
      'công nghệ',
      'chất liệu',
      'tính năng'
    ]
  ],

  [
    'brand',
    [
      'hãng nào',
      'thương hiệu',
      'của ai',
      'sản xuất',
      'nhà sản xuất'
    ]
  ],

  [
    'size',
    [
      'bảng size',
      'size áo',
      'size giày',
      'cỡ áo',
      'cỡ giày',
      'số giày',
      'form',
      'chọn size'
    ]
  ],

  [
    'price',
    [
      'giá bao nhiêu',
      'bao nhiêu tiền',
      'giá',
      'bao nhiêu',
      'tiền'
    ]
  ],

  [
    'greeting',
    [
      'xin chào',
      'hello',
      'hi',
      'chào',
      'hey',
      'alo',
      'xin chào bạn'
    ]
  ],

  [
    'order_tracking',
    [
      'tra cứu',
      'tra cứu đơn',
      'tra cứu đơn hàng',
      'đơn hàng',
      'kiểm tra đơn',
      'kiểm tra đơn hàng',
      'xem đơn',
      'xem đơn hàng',
      'tình trạng đơn',
      'trạng thái đơn',
      'mã đơn',
      'đơn của tôi',
      'đơn của mình'
    ]
  ]

];


// ============================================================
// 6. MATCH INTENT
// ============================================================

const matchedIntents = [];

for (const [key, keywords] of INTENT_MAP) {

  const matched =
    keywords.some(keyword =>
      fuzzyMatch(keyword, msg)
    );

  if (matched) {
    matchedIntents.push(key);
  }
}


let intent =
  matchedIntents[0] || 'general';

let secondaryIntents =
  matchedIntents.slice(1);


// ============================================================
// 7. POLICY INTENT
// ============================================================

const POLICY_INTENTS = [
  'exchange',
  'size',
  'shipping',
  'payment',
  'warranty'
];

const isPolicy =
  POLICY_INTENTS.includes(intent);


// ============================================================
// 8. TOKENIZE USER MESSAGE
// ============================================================

const STOP = new Set([
  'của',
  'và',
  'có',
  'không',
  'cho',
  'bao',
  'nhiêu',
  'giá',
  'còn',
  'thì',
  'sao',
  'muốn',
  'mua',
  'cái',
  'chiếc',
  'đôi',
  'như',
  'nào',
  'rồi',
  'này',
  'đó',
  'là',
  'gì',
  'với',
  'anh',
  'chị',
  'em',
  'shop',
  'ạ',
  'nhé'
]);


const tokens =
  msg
    .replace(/[?,!.:;]/g, ' ')
    .split(/\s+/)
    .map(token => token.trim())
    .filter(token => {
      return (
        token.length > 1 &&
        !STOP.has(token)
      );
    });


// ============================================================
// 9. PRODUCT SCORING
// ============================================================

function scoreProduct(product) {

  let score = 0;

  const name =
    String(product.name ?? '');

  const brand =
    String(product.brand ?? '');

  const category =
    String(product.category ?? '')
      .toLowerCase();

  const sport =
    String(product.sport ?? '')
      .toLowerCase();

  const description =
    String(product.description ?? '')
      .toLowerCase();


  for (const token of tokens) {

    if (name.includes(token)) {
      score += 10;
    }

    if (brand.includes(token)) {
      score += 8;
    }

    if (category.includes(token)) {
      score += 5;
    }

    if (sport.includes(token)) {
      score += 4;
    }

    if (description.includes(token)) {
      score += 1;
    }
  }

  return score;
}


// ============================================================
// 10. FAQ SCORING
// ============================================================

function scoreFaq(faq) {

  let score = 0;

  const keywords =
    String(faq.keywords ?? '');

  const topic =
    String(faq.topic ?? '')
      .toLowerCase();

  const answer =
    String(faq.answer ?? '')
      .toLowerCase();


  for (const token of tokens) {

    if (keywords.includes(token)) {
      score += 10;
    }

    if (topic.includes(token)) {
      score += 5;
    }

    if (answer.includes(token)) {
      score += 1;
    }
  }

  return score;
}


// ============================================================
// 11. FILTER PRODUCT
// ============================================================

let filteredProducts =
  products
    .map(product => ({
      ...product,
      score: scoreProduct(product)
    }))
    .filter(product =>
      product.score > 0
    )
    .sort(
      (a, b) =>
        b.score - a.score
    );


// ============================================================
// 12. FILTER FAQ
// ============================================================

let filteredFaqs =
  faqs
    .map(faq => ({
      ...faq,
      score: scoreFaq(faq)
    }))
    .filter(faq =>
      faq.score > 0
    )
    .sort(
      (a, b) =>
        b.score - a.score
    );


// ============================================================
// 13. GIỚI HẠN SẢN PHẨM
// ============================================================

const maxProducts =
  intent === 'compare'
    ? 4
    : 3;


if (
  filteredProducts.length === 0 &&
  tokens.length === 0 &&
  intent === 'general'
) {

  filteredProducts =
    products.slice(0, 3);

} else {

  filteredProducts =
    filteredProducts.slice(
      0,
      maxProducts
    );
}


// ============================================================
// 14. FAQ FALLBACK
// ============================================================

if (
  filteredFaqs.length === 0 &&
  isPolicy
) {

  const fallbackFaqs =
    faqs.filter(faq => {

      const topic =
        String(faq.topic ?? '')
          .toLowerCase();

      return topic.includes(intent);
    });


  if (fallbackFaqs.length > 0) {

    filteredFaqs =
      fallbackFaqs.slice(0, 3);

  } else {

    filteredFaqs =
      faqs.slice(0, 3);
  }

} else {

  filteredFaqs =
    filteredFaqs.slice(0, 3);
}


// ============================================================
// 15. BUILD PRODUCT CONTEXT
// ============================================================

let productContext = '';

for (const product of filteredProducts) {

  productContext +=
    `- [${product.id}] ` +
    `${product.name_orig} | ` +
    `Hãng: ${product.brand_orig || 'Không rõ'} | ` +
    `Giá: ${product.price.toLocaleString('vi-VN')} VNĐ | ` +
    `Tình trạng: ${product.stock}\n`;
}


// ============================================================
// 16. BUILD FAQ CONTEXT
// ============================================================

let faqContext = '';

for (const faq of filteredFaqs) {

  faqContext +=
    `- [${faq.topic}] ${faq.answer}\n`;
}


// ============================================================
// 17. EXTRACT ORDER INFO
// ============================================================

let msgForId =
  userMessage;

let orderPhone =
  null;

let orderId =
  null;


// ============================================================
// PHONE VIỆT NAM
// Ví dụ:
//
// 0912345678
// 091 234 5678
// 091-234-5678
// 091.234.5678
// +84 912 345 678
// 84912345678
// ============================================================

const phoneRegex =
  /(?:\+?84[\s.-]?|0)(?:3|5|7|8|9)(?:[\s.-]?\d){8}\b/;

const phoneMatch =
  userMessage.match(phoneRegex);


if (phoneMatch) {

  const rawPhone =
    phoneMatch[0];

  let rawDigits =
    rawPhone.replace(/\D/g, '');

  // Chuẩn hóa về 10 chữ số bắt đầu bằng 0
  if (rawDigits.startsWith('84')) {
    rawDigits =
      '0' + rawDigits.slice(2);
  }

  orderPhone =
    rawDigits;

  // Xóa phone trước khi tìm order ID
  msgForId =
    userMessage.replace(
      rawPhone,
      ' '
    );
}


// ============================================================
// ORDER ID
// Chỉ nhận số ĐỨNG ĐỘC LẬP:
// - 1-10 chữ số
// - không phải giá tiền (1.590.000) hoặc số thập phân
// - không dính đơn vị (125k, 42 size, 2 đôi...)
// - ưu tiên số đi sau từ khóa "mã đơn"/"đơn"
// ============================================================

function extractOrderId(text) {

  const lower =
    String(text ?? '').toLowerCase();

  // Loại bỏ giá tiền: 1.590.000 / 1,590,000
  const cleaned =
    lower
      .replace(
        /\d{1,3}(?:[.,]\d{3})+(?:[.,]\d+)?/g,
        ' '
      )
      // Loại bỏ số dính đơn vị: 125k, 125đ, 2 đôi, size 42...
      .replace(
        /\d+(?:[.,]\d+)?\s*(?:k|đ|d|vnd|vnđ|đồng|dong|nghìn|trieu|triệu|tr|%|cm|mm|kg|đôi|cái|chiếc|con|món|bộ|size|cỡ|sl)\b/g,
        ' '
      );

  // Ưu tiên số đi ngay sau từ khóa mã đơn/đơn hàng
  const afterKw =
    cleaned.match(
      /(?:mã đơn|mã đh|mã đơn hàng|đơn hàng|đơn|order|đh)\s*[#:\s]*(\d{1,10})\b/
    );

  if (afterKw) {
    return afterKw[1];
  }

  // Số đứng độc lập
  const standalone =
    cleaned.match(/\b(\d{1,10})\b/g);

  if (standalone && standalone.length > 0) {
    return standalone[0];
  }

  return null;
}


orderId =
  extractOrderId(msgForId);


// ============================================================
// 18. GREETING ONLY
// ============================================================

const isGreetingOnly =
  intent === 'greeting' &&
  tokens.length <= 2;


// ============================================================
// 19. PRODUCT IDS
// ============================================================

const mentionedProductIds =
  filteredProducts.map(
    product => product.id
  );


// ============================================================
// 20. CÓ CẦN FETCH ORDER KHÔNG
// ============================================================

const needOrderFetch =
  Boolean(
    orderPhone &&
    orderId &&
    intent === 'order_tracking'
  );


// ============================================================
// 21. FINAL OUTPUT
// ============================================================

return [
  {
    json: {

      chatId,

      userName:
        sanitize(userName),

      userMessage:
        sanitize(userMessage),

      intent,

      isPolicy,

      productContext:
        productContext.trim() ||
        'Không tìm thấy sản phẩm phù hợp',

      faqContext:
        faqContext.trim() ||
        'Không có FAQ phù hợp',

      orderPhone,

      orderId,

      needOrderFetch,

      timestamp:
        new Date().toISOString(),

      isGreetingOnly,

      secondaryIntents,

      mentionedProductIds,

      _rateLimited: false
    }
  }
];

// ============================================================
// BUILD PROMPT - THEXUONG TELEGRAM BOT
// ============================================================


// ============================================================
// 1. LẤY CONTEXT TỪ SMART FILTER + INTENT
// PHẢI KHAI BÁO TRƯỚC KHI DÙNG ctx
// ============================================================

const ctx = $('Smart Filter + Intent').item.json ?? {};


// ============================================================
// 2. RATE LIMIT
// ============================================================

if (ctx._rateLimited) {
  return [
    {
      json: {
        chatId: ctx.chatId,
        userName: ctx.userName || 'Bạn',
        userMessage: ctx.userMessage || '',
        intent: 'rate_limited',
        timestamp: ctx.timestamp || new Date().toISOString(),

        requestBody: null,

        _rateLimited: true,

        _reply:
          'Bạn đang gửi tin nhắn quá nhanh. Vui lòng chờ một chút rồi thử lại nhé! ⏳'
      }
    }
  ];
}


// ============================================================
// 3. TRA CỨU ĐƠN HÀNG — ĐÃ CHUYỂN SANG NHÁNH DETERMINISTIC RIÊNG
// (Parse Order Tracking / Format Order Response / Xử Lý Order Reply)
// Build Prompt không còn xử lý order.
// ============================================================


// ============================================================
// 4. ĐỌC MEMORY - LỊCH SỬ HỘI THOẠI
// ============================================================

let conversationHistory = [];

try {
  const memItems =
    $('Load Memory').all();

  if (
    memItems.length > 0 &&
    memItems[0]?.json?.history_json
  ) {
    const rawHistory =
      memItems[0].json.history_json;

    if (Array.isArray(rawHistory)) {
      conversationHistory = rawHistory;
    } else if (typeof rawHistory === 'string') {
      const parsed =
        JSON.parse(rawHistory);

      conversationHistory =
        Array.isArray(parsed)
          ? parsed
          : [];
    }
  }

} catch (e) {
  conversationHistory = [];
}


// Chỉ lấy 5 lượt gần nhất
conversationHistory =
  conversationHistory.slice(-5);


// ============================================================
// 5. ĐỌC MEMORY - SẢN PHẨM ĐÃ NHẮC TRƯỚC ĐÓ
// ============================================================

let lastMentionedProducts = [];

try {
  const memItems =
    $('Load Memory').all();

  if (
    memItems.length > 0 &&
    memItems[0]?.json?.last_mentioned
  ) {
    const rawMentioned =
      memItems[0].json.last_mentioned;

    if (Array.isArray(rawMentioned)) {
      lastMentionedProducts =
        rawMentioned;

    } else if (typeof rawMentioned === 'string') {
      const parsed =
        JSON.parse(rawMentioned);

      lastMentionedProducts =
        Array.isArray(parsed)
          ? parsed
          : [];
    }
  }

} catch (e) {
  lastMentionedProducts = [];
}


// ============================================================
// 6. XỬ LÝ CÂU THAM CHIẾU
// Ví dụ:
// "cái đó"
// "đôi đó"
// "sản phẩm này"
// ============================================================

const REFERENCE_WORDS = [
  'cái đó',
  'cái này',
  'sản phẩm đó',
  'sản phẩm này',
  'nó',
  'chúng',
  'đôi đó',
  'đôi này'
];

const safeUserMessage =
  String(ctx.userMessage ?? '');

const lowerUserMessage =
  safeUserMessage.toLowerCase();

const hasReference =
  REFERENCE_WORDS.some(word =>
    lowerUserMessage.includes(word)
  );


let referenceContext = '';

if (
  hasReference &&
  lastMentionedProducts.length > 0
) {
  referenceContext =
    '\n[LƯU Ý: Khách đang nhắc đến sản phẩm đã giới thiệu trước đó. ' +
    'Nếu sản phẩm nằm trong [SẢN PHẨM] thì trả lời. ' +
    'Nếu không thì hỏi lại khách "Bạn muốn hỏi về sản phẩm nào ạ?"]\n';
}


// ============================================================
// 7. BUILD HISTORY STRING
// ============================================================

let historyStr = '';

if (conversationHistory.length > 0) {
  historyStr =
    '[LỊCH SỬ HỘI THOẠI GẦN ĐÂY]\n';

  for (const turn of conversationHistory) {
    const userText =
      String(turn?.user ?? '');

    const botText =
      String(turn?.bot ?? '');

    historyStr +=
      `Khách: ${userText}\n` +
      `Tư vấn viên: ${botText}\n`;
  }

  historyStr += '\n';
}


// ============================================================
// 8. BUILD DATA BLOCK
// ============================================================

let dataBlock = '';

const productContext =
  String(
    ctx.productContext ??
    'Không tìm thấy sản phẩm phù hợp'
  );

const faqContext =
  String(
    ctx.faqContext ??
    'Không có FAQ phù hợp'
  );


const hasProduct =
  productContext !==
  'Không tìm thấy sản phẩm phù hợp';

const hasFaq =
  faqContext !==
  'Không có FAQ phù hợp';


if (hasProduct) {
  dataBlock +=
    `[SẢN PHẨM]\n${productContext}\n`;
}

if (hasFaq) {
  dataBlock +=
    `[CHÍNH SÁCH]\n${faqContext}\n`;
}

if (referenceContext) {
  dataBlock += referenceContext;
}


// ============================================================
// 9. HƯỚNG DẪN THEO INTENT
// ============================================================

const intentGuide = {

  greeting:
    'Chào hỏi thân thiện, giới thiệu mình là nhân viên TheXuong. Hỏi khách cần hỗ trợ gì.',

  stock:
    'Thông báo tình trạng tồn kho từ [SẢN PHẨM].',

  price:
    'Nêu giá sản phẩm từ [SẢN PHẨM].',

  describe:
    'Mô tả sản phẩm từ [SẢN PHẨM].',

  brand:
    'Xác nhận thương hiệu từ [SẢN PHẨM].',

  exchange:
    'Trả lời dựa nội dung [CHÍNH SÁCH] mục đổi trả.',

  size:
    'Trả lời dựa nội dung [CHÍNH SÁCH] mục size.',

  shipping:
    'Trả lời dựa nội dung [CHÍNH SÁCH] mục vận chuyển.',

  payment:
    'Trả lời dựa nội dung [CHÍNH SÁCH] mục thanh toán.',

  warranty:
    'Trả lời dựa nội dung [CHÍNH SÁCH] mục bảo hành.',

  compare:
    'So sánh các sản phẩm trong [SẢN PHẨM].',

  general:
    'Trò chuyện lịch sự. Nếu chưa rõ nhu cầu, hỏi khách đang quan tâm sản phẩm hoặc môn thể thao nào.'
};


const guide =
  intentGuide[ctx.intent] ||
  intentGuide.general;


// ============================================================
// 10. RULE ĐỘNG
// ============================================================

let rule2 = '';
let rule3 = '';


if (
  [
    'stock',
    'price',
    'describe',
    'brand',
    'compare'
  ].includes(ctx.intent)
) {

  rule2 =
    '2. NẾU KHÁCH HỎI VỀ MỘT SẢN PHẨM NHƯNG [SẢN PHẨM] TRỐNG ' +
    '→ Tuyệt đối không đoán thông tin. ' +
    'PHẢI trả lời rằng hiện tại chưa có thông tin về sản phẩm này và xin khách cung cấp thêm tên sản phẩm.\n';
}


if (
  [
    'exchange',
    'size',
    'shipping',
    'payment',
    'warranty'
  ].includes(ctx.intent)
) {

  rule3 =
    '3. NẾU KHÁCH HỎI CHÍNH SÁCH NHƯNG [CHÍNH SÁCH] TRỐNG ' +
    '→ Không tự bịa chính sách. Hướng dẫn khách liên hệ bộ phận hỗ trợ của TheXuong.\n';
}


if (ctx.intent === 'general') {

  rule2 =
    '2. NẾU KHÁCH HỎI VỀ SẢN PHẨM NHƯNG KHÔNG RÕ RÀNG ' +
    '→ Trả lời lịch sự và xin thêm tên sản phẩm hoặc nhu cầu cụ thể.\n';
}


// ============================================================
// 11. BUILD PROMPT
// ============================================================

const prompt =
`Bạn là AI tư vấn viên của TheXuong Sport Store. Tên bạn là TheXuong AI.

=== LUẬT TUYỆT ĐỐI (CẤM VI PHẠM) ===
0. CHỈ ĐƯỢC PHÉP TRẢ LỜI BẰNG TIẾNG VIỆT.
TUYỆT ĐỐI KHÔNG SỬ DỤNG TIẾNG TRUNG QUỐC.

1. KHÔNG TỰ BỊA ĐẶT THÔNG TIN.
Chỉ sử dụng dữ liệu được cung cấp bên dưới.

${rule2}${rule3}4. Trả lời tự nhiên, lịch sự, súc tích, ưu tiên dưới 80 từ.
5. Có thể dùng emoji phù hợp nhưng không lạm dụng.
6. Hướng dẫn riêng cho câu hỏi hiện tại: ${guide}

=== DỮ LIỆU ĐƯỢC CẤP ===
${dataBlock || '(Trống)'}
===========================

${historyStr}Khách (${ctx.userName || 'Bạn'}): ${safeUserMessage}
Tư vấn viên:`;


// ============================================================
// 12. OUTPUT CHO OLLAMA
// ============================================================

return [
  {
    json: {

      chatId:
        ctx.chatId,

      userName:
        ctx.userName || 'Bạn',

      userMessage:
        safeUserMessage,

      intent:
        ctx.intent || 'general',

      timestamp:
        ctx.timestamp ||
        new Date().toISOString(),

      _rateLimited:
        false,

      requestBody: {

        model:
          'qwen2.5:3b',

        prompt,

        stream:
          false,

        options: {
          temperature: 0.1,
          top_p: 0.85,
          num_predict: 600,
          repeat_penalty: 1.2
        }
      }
    }
  }
];

if ($json._rateLimited) {
  return [{ json: {
    chatId: $json.chatId,
    botReply: $json._reply,
    botReplyRaw: $json._reply,
    updatedHistory: [],
    timestamp: new Date().toISOString(),
  }}];
}

const ollamaResp = ($json.response || '').trim();
const buildCtx = $('Build Prompt').item.json;

const botReply = ollamaResp ||
  'Xin lỗi, hệ thống đang bận. Vui lòng thử lại sau! 🙏';

let history = [];
try {
  const memItems = $('Load Memory').all();
  if (memItems.length > 0 && memItems[0].json.history_json) {
    history = JSON.parse(memItems[0].json.history_json);
  }
} catch(e) {
  history = [];
}

history.push({ user: buildCtx.userMessage, bot: ollamaResp });
const updatedHistory = history.slice(-5);

return [{
  json: {
    chatId: buildCtx.chatId,
    userName: buildCtx.userName,
    userMessage: buildCtx.userMessage,
    intent: buildCtx.intent,
    botReply: botReply,
    botReplyRaw: ollamaResp,
    updatedHistory: updatedHistory,
    timestamp: buildCtx.timestamp,
    mentionedProductIds: buildCtx.mentionedProductIds || [],
  }
}];

// ============================================================
// CHUẨN BỊ SAVE MEMORY - THEXUONG TELEGRAM BOT
// Gửi cả historyJson + stateJson (nếu có thay đổi).
// ============================================================

const d = $json;
const historyJson = JSON.stringify(d.updatedHistory);
const now = new Date().toISOString();

// State: ưu tiên từ nhánh order (Xử Lý Order Reply),
// fallback là reset state khi timeout (Parse Order Tracking).
let stateJson = null;

try {
  const o = $('Xử Lý Order Reply').item.json;
  stateJson = o.stateJsonToPersist ?? null;
} catch (e) {
  stateJson = null;
}

if (stateJson === null) {
  try {
    const p = $('Parse Order Tracking').item.json;
    stateJson = p.resetStateJson ?? null;
  } catch (e) {
    stateJson = null;
  }
}

const payloadSave = {
  chatId: String(d.chatId),
  historyJson: historyJson,
  lastMentioned: JSON.stringify(d.mentionedProductIds || [])
};

// Chỉ gửi stateJson khi có thay đổi → backend giữ state cũ nếu không gửi
if (stateJson !== null && stateJson !== undefined) {
  payloadSave.stateJson = stateJson;
}

return [{
  json: {
    chatId: d.chatId,
    userName: d.userName,
    userMessage: d.userMessage,
    intent: d.intent,
    botReply: d.botReplyRaw,
    timestamp: d.timestamp,
    historyJson: historyJson,
    updatedAt: now,
    payloadSave: payloadSave,
    payloadLog: {
      chatId: String(d.chatId),
      userName: d.userName,
      intent: d.intent,
      userMessage: d.userMessage,
      botReply: d.botReplyRaw
    }
  }
}];

const response = ($json.response || '').trim();
const buildCtx = $('Build Prompt').item.json;
const dataBlock = buildCtx.requestBody.prompt;

// Nếu response rỗng
if (!response) {
  return [{ json: {
    ...$json,
    response: 'Xin lỗi bạn, hệ thống đang bận. Vui lòng thử lại sau! 🙏'
  }}];
}

// Check 1: Có ký tự Trung Quốc không?
const hasChinese = /[\u4e00-\u9fff]/.test(response);
if (hasChinese) {
  return [{ json: {
    ...$json,
    response: 'Xin lỗi bạn, mình chưa có thông tin chính xác. Bạn vui lòng liên hệ hotline để được hỗ trợ nhé! 🙏'
  }}];
}

// Check 2: Có bịa giá không? (So sánh giá trong response với data)
const pricesInResponse = response.match(/\d{1,3}(?:[.,]\d{3})*(?:\s*(?:VNĐ|đ|VND))/g) || [];
const pricesInData = dataBlock.match(/\d{1,3}(?:[.,]\d{3})*(?:\s*(?:VNĐ|đ|VND))/g) || [];
let hasFakePrice = false;
for (const p of pricesInResponse) {
  const normalized = p.replace(/[.,\s]/g, '');
  const found = pricesInData.some(dp => dp.replace(/[.,\s]/g, '') === normalized);
  if (!found && pricesInData.length > 0) {
    hasFakePrice = true;
    break;
  }
}
if (hasFakePrice) {
  return [{ json: {
    ...$json,
    response: 'Xin lỗi bạn, mình chưa có thông tin chính xác về giá sản phẩm này. Bạn vui lòng liên hệ shop để được báo giá nhé! 💰'
  }}];
}

// Check 3: Response quá dài
if (response.length > 1000) {
  return [{ json: {
    ...$json,
    response: response.substring(0, 800) + '...'
  }}];
}

// Pass through
return [{ json: $json }];

// ============================================================
// PARSE ORDER TRACKING - THEXUONG TELEGRAM BOT
// Merge state_json từ memory với dữ liệu trích từ message hiện tại.
// Quyết định order flow deterministically (KHÔNG qua Ollama).
// ============================================================

const ctx =
  $('Smart Filter + Intent').item.json ?? {};

const memJson =
  $json ?? {};

const TIMEOUT_MS =
  15 * 60 * 1000;


// ============================================================
// 1. ĐỌC STATE TỪ MEMORY
// ============================================================

let state = {};

try {
  const raw = memJson.state_json;

  if (typeof raw === 'string' && raw.trim()) {
    state = JSON.parse(raw);
  } else if (raw && typeof raw === 'object') {
    state = raw;
  }
} catch (e) {
  state = {};
}

const ol =
  (state.orderLookup &&
    typeof state.orderLookup === 'object')
    ? state.orderLookup
    : null;


// ============================================================
// 2. TIMEOUT CHECK (15 PHÚT)
// ============================================================

let pendingActive =
  Boolean(ol && ol.active === true);

let resetStateJson =
  null;

if (pendingActive && ol.startedAt) {
  const started =
    Date.parse(ol.startedAt);

  if (!isNaN(started) &&
      (Date.now() - started) > TIMEOUT_MS) {
    pendingActive = false;
    resetStateJson =
      '{"orderLookup":{"active":false,"phone":null,"orderId":null}}';
  }
}


// ============================================================
// 3. MERGE VỚI DỮ LIỆU MỚI TỪ MESSAGE
// ============================================================

let phone =
  ctx.orderPhone ?? null;

let orderId =
  ctx.orderId ?? null;

if (pendingActive) {
  if (!phone && ol.phone) {
    phone = ol.phone;
  }
  if (!orderId && ol.orderId) {
    orderId = ol.orderId;
  }
}


// ============================================================
// 4. QUYẾT ĐỊNH ORDER FLOW
// ============================================================

const rateLimited =
  Boolean(ctx._rateLimited);

const isOrderIntent =
  ctx.intent === 'order_tracking' ||
  (Array.isArray(ctx.secondaryIntents) &&
    ctx.secondaryIntents.includes('order_tracking'));

const orderFlowActive =
  (pendingActive || isOrderIntent) && !rateLimited;

const missingOrderPhone =
  !phone;

const missingOrderId =
  !orderId;

let needOrderFetch =
  false;

let pendingStateJson =
  null;

let askText =
  null;

if (orderFlowActive) {

  if (phone && orderId) {

    // Đủ cả 2 → fetch đơn ngay
    needOrderFetch = true;

  } else {

    // Giữ startedAt cũ nếu vẫn đang pending (không reset timeout mỗi message)
    const startedAt =
      (pendingActive && ol.startedAt)
        ? ol.startedAt
        : new Date().toISOString();

    pendingStateJson =
      JSON.stringify({
        orderLookup: {
          active: true,
          phone: phone ?? null,
          orderId: orderId ?? null,
          startedAt: startedAt
        }
      });

    if (missingOrderPhone && missingOrderId) {

      // Case A — thiếu cả phone và orderId
      askText =
        '📦 Được ạ. Bạn vui lòng cung cấp số điện thoại dùng khi đặt hàng nhé.';

    } else if (missingOrderPhone) {

      // Case C — có orderId, thiếu phone
      askText =
        '✅ Mình đã nhận mã đơn hàng.\n\nBạn gửi thêm số điện thoại đã dùng khi đặt hàng giúp mình nhé.';

    } else if (missingOrderId) {

      // Case B — có phone, thiếu orderId
      askText =
        '✅ Mình đã nhận số điện thoại.\n\nBạn gửi thêm mã đơn hàng giúp mình nhé.\nVí dụ: 125';

    }

  }

}


// ============================================================
// 5. OUTPUT
// ============================================================

return [
  {
    json: {

      chatId: ctx.chatId,
      userName: ctx.userName,
      userMessage: ctx.userMessage,

      intent:
        orderFlowActive
          ? 'order_tracking'
          : (ctx.intent || 'general'),

      isOrderFlow: orderFlowActive,

      orderPhone: phone,
      orderId: orderId,

      orderLookupActive: pendingActive,
      missingOrderPhone: missingOrderPhone,
      missingOrderId: missingOrderId,
      needOrderFetch: needOrderFetch,

      pendingStateJson: pendingStateJson,
      resetStateJson: resetStateJson,

      askText: askText,

      // Passthrough cho nhánh Ollama
      isPolicy: ctx.isPolicy,
      productContext: ctx.productContext,
      faqContext: ctx.faqContext,
      isGreetingOnly: ctx.isGreetingOnly,
      secondaryIntents: ctx.secondaryIntents,
      mentionedProductIds: ctx.mentionedProductIds,

      timestamp: ctx.timestamp || new Date().toISOString(),
      _rateLimited: ctx._rateLimited || false
    }
  }
];

// ============================================================
// FORMAT ORDER RESPONSE - THEXUONG TELEGRAM BOT
// Format kết quả tra cứu đơn TRỰC TIẾP - KHÔNG đi qua Ollama.
// Input: response từ "Lấy Dữ Liệu Đơn Hàng"
// ============================================================

const orderResp =
  $json ?? {};

const po =
  $('Parse Order Tracking').item.json ?? {};

const orderId =
  po.orderId ?? '?';


// Map status thực tế trong project (OrderStatus.java)
const STATUS_MAP = {
  PENDING: 'Chờ xử lý',
  CONFIRMED: 'Đã xác nhận',
  SHIPPING: 'Đang giao hàng',
  DELIVERED: 'Đã giao hàng',
  COMPLETED: 'Hoàn thành',
  CANCEL_REQUESTED: 'Chờ duyệt hủy',
  CANCELLED: 'Đã hủy',
  REFUNDED: 'Đã hoàn tiền'
};


let botReply;
let stateAfter;


if (orderResp.success && orderResp.data) {

  // ============ SUCCESS ============

  const d = orderResp.data;

  const total =
    Number(d.totalMoney ?? 0);

  const totalFmt =
    Number.isFinite(total)
      ? total.toLocaleString('vi-VN')
      : '0';

  const statusVn =
    STATUS_MAP[d.status] || 'Không rõ';

  let itemsText = 'Không rõ';

  if (Array.isArray(d.items) &&
      d.items.length > 0) {

    itemsText =
      d.items
        .map(item => String(item ?? ''))
        .filter(Boolean)
        .map(s => '• ' + s)
        .join('\n');
  }

  botReply =
    '📦 ĐƠN HÀNG #' + orderId + '\n\n' +
    '🟡 Trạng thái: ' + statusVn + '\n' +
    '💰 Tổng tiền: ' + totalFmt + ' VNĐ\n' +
    '💳 Thanh toán: ' + (d.paymentMethod || 'Không rõ') + '\n\n' +
    '🛍 Sản phẩm:\n' +
    itemsText + '\n\n' +
    'Nếu bạn cần hỗ trợ thêm về đơn này cứ nhắn mình nhé.';

  // Tra cứu xong → clear state
  stateAfter =
    '{"orderLookup":{"active":false,"phone":null,"orderId":null}}';

} else if (orderResp.success === false) {

  // ============ NOT FOUND (hợp lệ) ============

  botReply =
    'Mình không tìm thấy đơn hàng phù hợp với mã đơn và số điện thoại bạn cung cấp.\n\n' +
    'Bạn kiểm tra lại thông tin rồi gửi lại giúp mình nhé.';

  // Not-found hợp lệ → clear state
  stateAfter =
    '{"orderLookup":{"active":false,"phone":null,"orderId":null}}';

} else {

  // ============ API LỖI / KHÔNG XÁC ĐỊNH ============
  // Không expose stack trace / URL nội bộ
  // Giữ state để khách retry

  botReply =
    'Hệ thống tra cứu đơn hàng đang tạm thời gặp sự cố. Bạn vui lòng thử lại sau nhé.';

  stateAfter =
    null;

}


return [
  {
    json: {

      ...$json,

      botReply: botReply,
      stateAfter: stateAfter,

      _orderFetched: true
    }
  }
];

// ============================================================
// XỬ LÝ ORDER REPLY - THEXUONG TELEGRAM BOT
// Deterministic: KHÔNG qua Ollama.
// 2 nhánh đầu vào (cùng input index 0, phân biệt theo content):
//   Ask path   (thiếu field)  - item có askText
//   Fetch path (có kết quả)   - item có botReply / stateAfter
// Output cùng shape với "Xử Lý Phản Hồi AI" để tái sử dụng
// Chuẩn Bị Save Memory + Gửi Phản Hồi Telegram.
// ============================================================

const item =
  $json ?? {};

const po =
  $('Parse Order Tracking').item.json ?? {};


// ============================================================
// 1. HISTORY TỪ MEMORY
// ============================================================

let history = [];

try {
  const memItems =
    $('Load Memory').all();

  if (memItems.length > 0) {
    const raw =
      memItems[0]?.json?.history_json;

    if (typeof raw === 'string' && raw.trim()) {
      history = JSON.parse(raw);
    } else if (Array.isArray(raw)) {
      history = raw;
    }
  }
} catch (e) {
  history = [];
}


// ============================================================
// 2. CHỌN REPLY + STATE
// ============================================================

const userMessage =
  po.userMessage ?? item.userMessage ?? '';

let botReply;
let stateJsonToPersist;

if (item.askText !== undefined &&
    item.askText !== null) {

  // ============ ASK PATH (thiếu field) ============

  botReply =
    item.askText;

  stateJsonToPersist =
    po.pendingStateJson ?? null;

} else {

  // ============ FETCH PATH (có kết quả) ============

  botReply =
    item.botReply ||
    'Hệ thống tra cứu đơn hàng đang tạm thời gặp sự cố. Bạn vui lòng thử lại sau nhé.';

  stateJsonToPersist =
    item.stateAfter ?? null;

}


// ============================================================
// 3. CẬP NHẬT HISTORY
// ============================================================

history.push({
  user: userMessage,
  bot: botReply
});

const updatedHistory =
  history.slice(-5);


// ============================================================
// 4. OUTPUT (cùng shape với Xử Lý Phản Hồi AI)
// ============================================================

return [
  {
    json: {

      chatId:
        po.chatId,

      userName:
        po.userName || 'Bạn',

      userMessage:
        userMessage,

      intent:
        'order_tracking',

      botReply:
        botReply,

      botReplyRaw:
        botReply,

      updatedHistory:
        updatedHistory,

      timestamp:
        po.timestamp || new Date().toISOString(),

      mentionedProductIds:
        po.mentionedProductIds || [],

      stateJsonToPersist:
        stateJsonToPersist
    }
  }
];
